export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    // API Routing: Music Discovery Feed & General Search Routes
    if (url.pathname === '/api/music' || url.pathname === '/api/search') {
      return handleMusicRequest(url, env);
    }

    // Tab Icon Dependency Routing: Serve the base64 injector script dynamically to the browser
    if (url.pathname === '/tabThumb.js') {
      return new Response(getTabThumbScript(), {
        headers: {
          'Content-Type': 'application/javascript; charset=utf-8',
          'Cache-Control': 'public, max-age=86400'
        }
      });
    }

    // Main App Routing: Serve clean UI markup with provided CSS
    return new Response(getHTMLTemplate(), {
      headers: {
        'Content-Type': 'text/html; charset=utf-8',
        'X-XSS-Protection': '1; mode=block',
        'X-Content-Type-Options': 'nosniff'
      }
    });
  }
};

async function handleMusicRequest(url, env) {
  const query = url.searchParams.get('q') || '';
  const pageToken = url.searchParams.get('pageToken') || '';
  const apiKey = env.YOUTUBE_API_KEY || url.searchParams.get('fallbackKey');
  
  // Detect if we should restrict explicitly to music categories based on endpoint pathing
  const isStrictMusicMode = url.pathname === '/api/music';

  if (!apiKey) {
    return createJSONResponse({ error: 'Missing YouTube API Key. Please bind YOUTUBE_API_KEY or provide one via the settings field.' }, 400);
  }

  try {
    let finalMusicQuery = query;
    if (!finalMusicQuery) {
      finalMusicQuery = isStrictMusicMode ? 'popular music hits' : 'trending videos';
    }

    // videoCategoryId=10 isolates music content natively inside YouTube's indexes
    let musicEndpoint = `https://www.googleapis.com/youtube/v3/search?part=snippet&type=video&maxResults=12&q=${encodeURIComponent(finalMusicQuery)}&pageToken=${pageToken}&key=${apiKey}`;
    
    if (isStrictMusicMode) {
      musicEndpoint += `&videoCategoryId=10`;
    }

    const response = await fetch(musicEndpoint);
    const searchData = await response.json();

    if (searchData.error) {
      return createJSONResponse({ error: searchData.error.message }, response.status);
    }

    const compiledItems = await enrichVideoMetaData(searchData.items, apiKey);
    return createJSONResponse({
      items: compiledItems,
      nextPageToken: searchData.nextPageToken || null
    });
  } catch (error) {
    return createJSONResponse({ error: `Internal Server Error: ${error.message}` }, 500);
  }
}

/**
 * Combines search endpoint results with specific contentDetails data to acquire durations
 */
async function enrichVideoMetaData(items, apiKey) {
  if (!items || items.length === 0) return [];

  const videoIds = items.map(item => item.id.videoId).filter(Boolean).join(',');
  if (!videoIds) return [];

  const detailsEndpoint = `https://www.googleapis.com/youtube/v3/videos?part=contentDetails&id=${videoIds}&key=${apiKey}`;
  const response = await fetch(detailsEndpoint);
  const detailData = await response.json();

  const durationMap = {};
  if (detailData.items) {
    detailData.items.forEach(item => {
      durationMap[item.id] = parseISO8601Duration(item.contentDetails.duration);
    });
  }

  return items.map(item => {
    const vId = item.id.videoId;
    return {
      id: vId,
      title: item.snippet.title,
      channelTitle: item.snippet.channelTitle,
      thumbnail: item.snippet.thumbnails?.high?.url || item.snippet.thumbnails?.medium?.url || '',
      duration: durationMap[vId] || '0:00'
    };
  });
}

/**
 * Translates standard ISO 8601 Durations (PT#M#S) into clean track formats
 */
function parseISO8601Duration(durationStr) {
  const regex = /PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/;
  const matches = durationStr.match(regex);
  if (!matches) return '0:00';

  const hours = matches[1] ? parseInt(matches[1], 10) : 0;
  const minutes = matches[2] ? parseInt(matches[2], 10) : 0;
  const seconds = matches[3] ? parseInt(matches[3], 10) : 0;

  let formatted = '';
  if (hours > 0) {
    formatted += hours + ':';
    formatted += (minutes < 10 ? '0' : '') + minutes + ':';
  } else {
    formatted += minutes + ':';
  }
  formatted += seconds < 10 ? '0' + seconds : seconds;
  return formatted;
}

/**
 * Utility response assembler
 */
function createJSONResponse(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      'Content-Type': 'application/json',
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET, OPTIONS',
      'Access-Control-Allow-Headers': '*'
    }
  });
}

/**
 * Generates the external tabThumb.js dependency containing the base64 favicon injector logic.
 * This runs safely as text inside the worker, and evaluates only when reaching the web browser.
 */
function getTabThumbScript() {
  return `(function() {
  const base64Favicon = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==";
  
  let link = document.querySelector("link[rel~='icon']");
  if (!link) {
    link = document.createElement('link');
    link.rel = 'icon';
    document.getElementsByTagName('head')[0].appendChild(link);
  }
  link.type = 'image/png';
  link.href = base64Favicon;
})();`;
}

